WHERE 1 = 1
AND (l.is_deleted = 0 OR l.is_deleted IS NULL)

    AND l.tenant_id = #{tenantId}


    AND l.query_type = #{queryType}


    AND l.status = #{status}


    AND l.conversation_id = #{conversationId}


    AND l.trace_id = #{traceId}


    AND f.rating = #{rating}


    AND f.created_by = #{createdBy}
